INSERT INTO `about_biffl` (`id`, `about_biffl`, `about_image`, `background`, `background_image`, `vission`, `vission_image`, `mission`, `mission_image`, `goal`, `goal_image`, `objectives`, `strategic`, `strategic_image`, `add_info1`, `add_info2`, `add_info3`, `status`, `updated_at`) VALUES
(1, '<p>Bangladesh Infrastructure Finance Fund Limited (BIFFL) is a Government-owned Non-Banking Financial Institution, operating since 2011. It is established by a resolution of the Cabinet of the Government of Bangladesh and owned by the Ministry of Finance, GOB</p>\r\n<p>Bangladesh Infrastructure Finance Fund Limited (BIFFL) is the biggest Non-Banking Financial Institution in Bangladesh owned by Government having authorized capital and paid up capital of BDT 100 billion and BDT 20.10 billion respectively. Addressing the importance of infrastructure development vis-&agrave;-vis insufficient investment in that particular sector, with a view to promote an attractive environment for sustainable private investment. As a part of this, BIFFL was established in 2011 as a special purpose vehicle to mobilize the PPP budget through financing infrastructure projects building partnership with private sector investors. Apart from that, to uphold sustainable development, BIFFL is also committed to protect environment and adopt eco-friendly measures in all aspects which are of its foremost priority while considering any investment transaction</p>', 'about (1).jpg', '<p>Bangladesh is an emerging economy. It has enormous potential to be a developed country. However, lack of infrastructure is holding it back from growing rapidly. So, investing in infrastructure is not only a business deal or opportunity, but also a national call that we cannot deny. Our coordinated approach can ensure economic growth of the country which will eventually raise the standard of living and quality of life for all.</p>\r\n<p>Bangladesh Infrastructure Finance Fund Limited (BIFFL) is a Government-owned Non-Banking Financial Institution, operating since 2011. It was established to address the importance and urgency of investing in the infrastructures of the country. Ministry of Finance is the key shareholder of the company. Memorandum of the company allows to include private partners later on.</p>\r\n<p>BIFFL envisages attracting private investment from local &amp; foreign investors and to invest in companies that are implementing infrastructure projects in Bangladesh. BIFFL is also committed to protect environment. Green economy and eco-friendly measures are our foremost priority while considering any investment deal.</p>', 'background.jpg', '<p>Acceleration of economic growth by leveraging relative strengths of Public and Private Sector through financing Infrastructure Projects.</p>', 'asset4.png', '<ul style=\"box-sizing: border-box; margin: 0px; list-style: outside none none; padding: 0px 0px 0px 10px; color: #363636; font-family: Roboto, sans-serif; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To perform as a professional Financial Institution by adopting the internationally accepted best practices and maintaining highest level of moral and ethical standards.</li>\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To promote Country&rsquo;s economic development by facilitating and encouraging Private Sector Investment in all infrastructure projects.</li>\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To support sustainable economic growth of Bangladesh through facilitating Infrastructure Development.</li>\r\n</ul>', NULL, '<ul style=\"list-style-type: circle;\">\r\n<li>To provide long-term finance to critically important infrastructure projects.</li>\r\n<li>To catalyze co-financing from private financial sources.</li>\r\n<li>To provide a unique vehicle for capital market development by exploring a number of avenues to capture domestic and foreign investment within the contexts of a robustly designed and well-governed investment vehicle.</li>\r\n</ul>', 'goal.jpg', '<ul style=\"list-style-type: circle;\">\r\n<li>To promote, encourage and finance Private Sector Investment in all infrastructure sector.</li>\r\n<li>To extend financing facilities for the infrastructure projects in the form of debt or equity.</li>\r\n<li>To attract private investment in long term infrastructure projects: overcoming the asset liability mismatch of existing bank finance.</li>\r\n<li>To create funds, sub-funds, including Islamic Funds, and any other type of Funds as deemed appropriate by the Company.</li>\r\n</ul>', '<ul style=\"box-sizing: border-box; margin: 0px; list-style: outside none none; padding: 0px 0px 0px 10px; color: #363636; font-family: Roboto, sans-serif; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To develop, finance &amp; monitor and implement infrastructure projects.</li>\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To focus on recruitment and retention of skilled, honest, creative and talented manpower.</li>\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To ensure transparency, accountability, fairness in operation and zero tolerance on corruption and sexual harassment.</li>\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To maximize shareholder equity by maintaining asset quality with balanced and sustainable growth.</li>\r\n<li style=\"box-sizing: border-box; list-style-type: circle;\">To enhance brand image through excellent customer service, CSR activities and finance in green &amp; energy efficient projects.</li>\r\n</ul>', 'asset10.png', 'about.jpg', NULL, NULL, 1, '2023-07-11 05:58:59');
INSERT INTO `blog` (`id`, `title`, `image`, `description`, `category`, `date`, `place`, `status`, `add_info`, `created_at`, `updated_at`) VALUES
(1, 'জাতীয় শোক দিবস ২০২২', 'notstil2l.PNG', '<p><span style=\"color: #444444; font-family: Roboto; font-size: 16px;\">স্বাধীনতার মহান স্থপতি জাতির পিতা বঙ্গবন্ধু&nbsp; শেখ মজিবুর রাহমানের ৪৭তম শাহাদৎ বার্ষিকীতে ১৫ আগষ্ট ২০২২ জাতীয় শোক দিবসের সকালে বিআইএফএফএল-এর প্রধান কার্যালয়ে যথাযথ ভাবগাম্ভীর্যের মধ্য দিয়ে জাতীয় পতাকা উত্তোলন ও অর্ধনমিত করে দিবসের কর্মসূচি শুরু করা হয়। প্রধান নির্বাহী কর্মকর্তা এস, এম, আনিজ্জামান প্রতিষ্ঠানের কর্মকর্তা ও কর্মচারীদের উপস্থিতিতে জাতীয় পতাকা উত্তোলন ও অর্ধনমিত করেন এবং কালো ব্যাজ ধারন কর্মসূচী পালন করেন। পরবর্তীতে পবিত্র কোরআন তেলাওয়াত, মিলাদ ও দোয়া, বৃক্ষরোপণ&nbsp; ও এতিমদের মাঝে খাদ্য বিতরন করা হয়।</span></p>', 1, '2022-08-15 12:50:57', NULL, 1, '1', '2022-11-16 05:53:31', 'জাতীয়-শোক-দিবস-২০২২-'),
(2, 'BIFFL Distributes Relief to  Flood Victims', '02-CSR.jpg', '<p><span style=\"color: #363636; font-family: Roboto; font-size: 15px; text-align: center; white-space: break-spaces;\">On 16 September 2018, as part of its corporate social responsibility (CSR) activities, BIFFL gave away relief goods (basic food stuff) to 500 families marooned by the flood in Fatikchhari and Hathazari of Chattogram.</span></p>', 1, '2022-11-09 05:30:32', NULL, 1, '1', '2022-11-16 06:06:09', 'BIFFL-Distributes-Relief-to--Flood-Victims'),
(3, 'Blood Donation Program on National  Mourning Day', '03-CSR.jpg', '<p><span style=\"color: #363636; font-family: Roboto; font-size: 15px; text-align: center; white-space: break-spaces;\">BIFFL, on the occasion of \"National Mourning Day\" organized a voluntary blood donation program on 12th August 2018 at its head office premises. BIFFL officials and staff as well as number of other donors participated in the blood donation program. </span></p>', 1, '2022-11-08 05:25:00', NULL, 1, '1', '2022-11-16 06:07:35', 'Blood-Donation-Program-on-National--Mourning-Day'),
(4, 'BIFFL inaugurated a voluntary donation plat form', '01-CSR.jpg', '<p><span style=\"color: #363636; font-family: Roboto; font-size: 15px; text-align: center; white-space: break-spaces;\">BIFFL inaugurated a voluntary donation platform \'Manush Manusher Jonno\' in front of its Kakrail office. The platform was opened with contribution from BIFFL\'s officials. BIFFL also provides pure drinking water to passers-by through a tap installed on the outer wall of its Kakrail office. </span></p>', 1, '2022-11-01 05:25:41', NULL, 2, '1', '2022-11-16 06:08:39', 'BIFFL-inaugurated-a-voluntary-donation-plat-form'),
(5, 'BIFFL contributed portable X-Ray machine to Dhaka Shishu (children) Hospital under Corporate Social Responsibility  (CSR)', 'x-Ray.jpg', '<p><span style=\"color: #363636; font-family: Roboto; font-size: 15px; text-align: center; white-space: break-spaces;\">Bangladesh Infrastructure Finance Fund Limited (BIFFL) has contributed portable X-Ray machine(GE mA Mobile Radiography X-Ray, Model: Brivo XR115) to Dhaka Shishu (Children) Hospital on 29th December 2019. Mr. Sagir Hossain Khan, COO, BIFFL donated the machine to the hospital Director (Acting), Professor (Dr.) Farid Ahmed in the presence Prof. Dr.Shireen Afroz, Professor of Paediatrics Nephrology, Professor Mohammed Hanif, Department of Paediatrics as a part of BIFFL\'s CSR activities. Mr. Sheikh Anower Sadat, Head of Project Finance, BIFFL, Mr. Muhammed Shahjahan. Unit Head of HR &amp; Administration, BIFFL were also present there. </span></p>', 1, '2022-09-07 00:00:00', NULL, 2, '1', '2022-11-16 06:09:35', 'BIFFL-contributed-portable-X-Ray-machine-to-Dhaka-Shishu-(children)-Hospital-under-Corporate-Social-Responsibility--(CSR)'),
(6, 'BIFFL WINS THE 3RD HIGHEST TAXPAYER AWARD FOR 2019-2020', 'tax-500x418.png', '<p><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">Bangladesh Infrastructure Finance Fund Limited (BIFFL) has been awarded as &lsquo;The 3</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">rd</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;Highest Taxpayer for 2019-2020&rsquo; in the category of Non-Bank Financial Institution. Mr. Golam Dastagir Gazi (Birpatik), MP, Minister for Textile and Jute, handed over the Crest &amp; Tax Card to Mr. S. M. Anisuzzaman, CEO of BIFFL at the occasion held on 11 February 2021 in the Capital. The program was presided over by Mr. Md. Iqbal Hossain, Commissioner (Tax), Large Taxpayers Unit while Mr. Apurba Kanti Das, Member (Tax Appeal &amp; Exemption), National Board of Revenue, Mr. Md. Rezaul Karim Chowdhury, Director General of BCS (Tax) Academy and other high officials of the Government attended on the occasion.</span></p>', 1, '2022-11-16 10:50:13', NULL, 1, '1', '2022-11-16 06:11:14', 'BIFFL-WINS-THE-3RD-HIGHEST-TAXPAYER-AWARD-FOR-2019-2020'),
(7, 'BIFFL WINS THE 2ND HIGHEST TAXPAYER AWARD FOR 2020-2021', '2.jpg', '<p><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">Bangladesh Infrastructure Finance Fund Limited (BIFFL) has been awarded as &lsquo;The 2</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">nd</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;Highest Taxpayer for 2020-2021&rsquo; in the category of Non-Bank Financial Institution. Mr. Abu Hena Md. Rahmatul Muneem, Senior Secretary, Internal Resources Division, Ministry of Finance and Chairman, NBR, handed over the award and the tax cards to Mr. S. M. Anisuzzaman, CEO of BIFFL at the occasion held on 24 November 2021 in the Officer&rsquo;s Club, Dhaka. Mr. A H M Mustafa Kamal, FCA, MP, Hon&rsquo;ble Finance Minister, embellished the event as the chief guest, while Md Jashim Uddin, president, FBCCI, was present as the special guest.</span></p>', 1, '2022-11-17 06:25:22', NULL, 1, '1', '2022-11-16 06:12:17', 'BIFFL-WINS-THE-2ND-HIGHEST-TAXPAYER-AWARD-FOR-2020-2021'),
(8, 'BIFFL SIGNED SUBSIDIARY LOAN AGREEMENT WITH FINANCE DIVISION, MOF UNDER JICA’S EECPFP', 'Signing-1-300x146.jpg', '<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; text-align: justify; margin: 0px 0px 10px !important 0px;\">Bangladesh Infrastructure Finance Fund Limited (BIFFL) signed a Subsidiary Loan Agreement (SLA) with the Finance Division, Ministry of Finance (MoF) on 02 January 2020 as the executing agency under Phase-2 of JICA&rsquo;s&nbsp; Energy Efficiency and Conservation Promotion Financing Project (EECPFP). Mr. Md. Ekhlasur Rahman, Additional Secretary, Finance Division, Ministry of Finance, GoB and the CEO (additional charge) of BIFFL and and Mr. Shirajun Noor Chowdhury, Joint Secretary, Finance Division, Ministry of Finance, GoB signed the Agreement on behalf of their respective organization.</p>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; text-align: justify; margin: 0px 0px 10px !important 0px;\">The loan facility of JPY 9500 million has been extended to BIFFL for carrying out the funding facility under EECPFP aiming to promote energy efficient technology, machinery and equipment in Bangladesh. It is expected that energy efficient technology will reduce the consumption of power in manufacturing sector which has a great impact on emission of green house gas and the climate.</p>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; margin: 0px 0px 10px !important 0px;\">The original fund is the concessional loan extended from the government of Japan (JICA) to the government of Bangladesh.</p>', 1, '2022-11-10 06:25:56', NULL, 1, '1', '2022-11-16 07:05:39', 'BIFFL-SIGNED-SUBSIDIARY-LOAN-AGREEMENT-WITH-FINANCE-DIVISION,-MOF-UNDER-JICA’S-EECPFP'),
(9, 'BIFFL WINS 19TH ICAB NATIONAL AWARD AND SAFA AWARD', 'biffl-300x300.jpg', '<p style=\"text-align: justify;\"><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">Bangladesh Infrastructure Finance Fund Ltd. (BIFFL) has won the 1</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">st</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;prize in the 19</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">th</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;ICAB National Award and the 2</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">nd</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;Runner Up prize in SAFA Best Presented Annual Report Award and SAARC Anniversary Award for Corporate Governance disclosure in Annual Report, 2018 in the category of Public Sector Entities. The Honorable Commerce Minister, Mr. Tipu Munshi, MP handed over the award to BIFFL&rsquo;s representatives in a program arranged on 30</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">th</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;November 2019 in the Capital. The Comptroller and Auditor General of Bangladesh, Mr. Mohammad Muslim Chowdhury, The Chairman of Financial Reporting Council Bangladesh, Mr. CQK Mustaq Ahmed and ICAB president Mr. A F Nesaruddin FCA also attended the program.</span></p>', 1, '2022-11-10 06:10:32', NULL, 1, '1', '2022-11-16 07:06:32', 'BIFFL-WINS-19TH-ICAB-NATIONAL-AWARD-AND-SAFA-AWARD'),
(10, 'THE 9TH ANNUAL GENERAL MEETING BANGLADESH INFRASTRUCTURE FINANCE FUND', '9th.png', '<p><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">BIFFL hosted its Annual General Meeting (AGM) recently on a virtual online platform, says a statement.</span><br style=\"box-sizing: border-box; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\" /><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">The shareholders in the meeting approved Audited Financial Statements for the year 2019 and cash dividend of BDT181.20 million (BDT18.12 crore). The company&rsquo;s paid-up capital during the year stood at BDT21.08 billion (BDT2,108.00 crore). For the year 2019, BIFFL has contributed an amount of BDT760.40 million (BDT76.04 crore) as income tax to the Government Exchequer. In the same year, BIFFL earned a total revenue of BDT2.20 billion (BDT220 crore) and made a net profit of BDT453 million (BDT45.30 crore).</span><br style=\"box-sizing: border-box; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\" /><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">BIFFL is a state-owned specialized financial institution of Bangladesh promoting infrastructure with emphasis on Public-Private Partnership (PPP) projects. Apart from that it has been sincerely channeling development partners&rsquo; funds in the energy efficiency and environment-friendly sectors as well as in other infrastructure projects in order to facilitate sustainable development of the country.</span><br style=\"box-sizing: border-box; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\" /><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">Mr. Abdur Rouf Talukder, Chairman of BIFFL and Senior Secretary to the Finance Division, Ministry of Finance, presided over the 9th AGM of BIFFL. Other directors and shareholders, including Mr. Md. Anisur Rahman, Senior Secretary, Energy and Mineral Resources Division; Mr. Md. Nazrul Islam, Secretary, Road Transport and Highways Division; Mr. Mohammed Belayet Hossain, Secretary, Bridges Division; Dr. Sultan Ahmed, Secretary, Power Division; Mr. M. Tofazzel Hossain Miah, Secretary, Prime Minister&rsquo;s Office; Ms. Fatima Yasmin, Secretary, Economic Relations Division; Mr. Md. Ekhlasur Rahman, Additional Secretary, Finance Division and Mr. S. M. Anisuzzaman, Chief Executive Officer, BIFFL attended the AGM. The Company Secretary of BIFFL, representative of the Finance Division, Ministry of Finance and the external Auditor were also attended the meeting.</span></p>', 1, '2022-11-16 10:50:00', NULL, 1, '1', '2022-11-16 07:08:10', 'THE-9TH-ANNUAL-GENERAL-MEETING-BANGLADESH-INFRASTRUCTURE-FINANCE-FUND'),
(11, 'PM\'s Relief and Welfare Fund', 'Capture.PMO2_v2.png', '<p>S.M. Anisuzzaman handed over a cheque amounting to BDT50,000 in favor of the PM\'s Relief and Welfare Fund to the Principal Secretary Dr Ahmed Kaikaus in the presence of the Honorable Prime Minister Sheikh Hasina.</p>', 2, '2022-06-26 11:15:15', NULL, 1, '1', '2023-07-16 09:31:02', 'PM\'s-Relief-and-Welfare-Fund'),
(12, 'Assistance to Kidney Patient', 'Kidney Patient_CSR.JPG', '<p><span style=\"font-size: 11pt; font-family: Calibri, sans-serif;\">In the presence of the Senior Management of BIFFL, the honorable CEO, Mr. S.M. Anisuzzaman handed over a cheque amounting to BDT 4,20,000.00 to a kidney patient as assistance for the expensive kidney disease treatment.&nbsp;</span></p>', 2, '2022-12-22 15:15:15', NULL, 1, '1', '2023-07-16 09:34:21', 'Assistance-to-Kidney-Patient'),
(13, 'Blanket Distribution', 'DSC_0501.JPG', '<p style=\"text-align: justify;\"><span style=\"font-size: 11pt; font-family: Calibri, sans-serif;\">Blanket distribution to vulnerable orphans was organized by BIFFL during an extremely cold winter in January 2023.</span></p>', 2, '2023-01-08 15:15:15', NULL, 1, '1', '2023-07-16 09:35:54', 'Blanket-Distribution'),
(14, 'FINANCIAL LITERACY DAY 2023', 'Financial_literacy_day.jpg', '<p style=\"text-align: justify;\"><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">Bangladesh Infrastructure Finance Fund Limited (BIFFL) celebrated &ldquo;Financial Literacy Day 2023&rdquo; at its corporate office on 6</span><span style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-size: 12px; line-height: 0; position: relative; top: -0.5em; color: #444444; font-family: \'PT Sans\';\">th</span><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">&nbsp;March 2023 by exchanging views with its clients.&nbsp; The Chief Executive Officer, Chief Operating Officer, and other executives/officials of the organization were present on the occasion. Clients from different segments, like small entrepreneurs, women, working adults, etc. attended the program to get valuable insights.</span></p>', 5, '2023-03-06 11:00:45', NULL, 1, '1', '2023-09-21 11:20:30', 'FINANCIAL-LITERACY-DAY-2023');
