INSERT INTO `vmsl_csr` (`id`, `name`, `type`, `thumbnail`, `details`, `status`) VALUES
(1, 'NHFIL donated 200 school bags to Madaripur Social Service Club that we handed over to 200 autistic children.', 'EDUCATION', '01-CSR.jpg', '<p><span style=\"border-radius: 0px; text-align: justify; color: #222222; font-family: arial, helvetica, sans-serif; font-size: small;\">NHFIL</span><span style=\"font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify; display: inline !important;\">&nbsp;donated 200 school bags to Madaripur Social Service Club that we handed over to 200 autistic children.</span></p>', 1),
(2, 'Ucchash School of Son Pocha Char', 'EDUCATION', '02-CSR.jpg', '<p><span style=\"font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify; display: inline !important;\">সোনা পোচা নামে বগুড়ার একটি দূরবর্তী চরে বসবাস করে ১0,000 জন সংগ্রামরত মানুষ,যারা প্রতিদিন একটি জীবিকার জন্য লড়াই করে। NHFIL&nbsp; এ চরের শিশুদের জন্য স্কুল নির্মাণের উদ্যোগ নেয়, যেসব শিশুরা কখনোই স্বপ্নেও ভাবেনি তারা একদিন শিক্ষা অর্জন করার সুযোগ পাবে। আইপিডিসি ফাইন্যান্স বিশ্বাস করে যে, বঞ্চিত শিশুদের সুন্দর আগামীর জন্য শুধুমাত্র শিক্ষার শিল্প সৃজনশীল অভিব্যক্তি এবং জ্ঞানের মধ্যে আনন্দে জাগিয়ে তুলতে পারে।</span></p>', 1),
(3, 'NHFIL supported the two-day-long awareness campaign included Hb.', 'HEALTH', '03-CSR.jpg', '<p><span style=\"font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify; display: inline !important;\">NHFIL supported the two-day-long awareness campaign included Hb.</span><br style=\"border-radius: 0px; font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify;\" /><span style=\"font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify; display: inline !important;\">Electrophoresis Test for carrier detection and a blood donation programme for the thalassemia patients, conducted by Bangladesh Thalassemia Samity.</span><br style=\"border-radius: 0px; font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify;\" /><span style=\"font-family: \'Open Sans\', Helvetica, Arial, sans-serif; font-size: 14px; text-align: justify; display: inline !important;\">A photography exhibition by Mr Noor Alam, along with interactive games and quizzes were also arranged to create awareness among the students.</span></p>', 1);
INSERT INTO `vmsl_deposit` (`id`, `name`, `short_description`, `show_home_page`, `thumbnail`, `image`, `details`, `feature`, `category`, `priority`, `eligibility`, `types_deposit`, `interest_rate`, `status`) VALUES
(1, 'Housing Deposit Scheme', 'To have an ownership of a flat / home with your savings and availability of Home loan facility of maximum 4 (four) times of savings amount from NHFIL.', 1, '1598423576-31631175.jpg', '1580743257-49104481.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">To have an ownership of a flat / home with your savings and availability of Home loan facility of maximum 4 (four) times of savings amount from NHFIL.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit on monthly installment basis.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Competitive rate of return and highest level of safety.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Eligibility: Minimum age - 18 years.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">To have an ownership of a flat / home with your savings and availability of Home loan facility of maximum 4 (four) times of savings amount from NHFIL.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit on monthly installment basis.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Competitive rate of return and highest level of safety.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Eligibility: Minimum age - 18 years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">&nbsp;</p>', 2, 0, NULL, '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Tenure: 7, 10 &amp; 12 years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Minimum deposit amount BDT 5,000/- per month.</p>', '.', 1),
(2, 'Money Multiplier Scheme', 'Under this scheme, your money can be increased multiple times over a period of time.', 1, '1598422415-31594989.jpg', '1580743257-49104481.jpg', '<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Under this scheme, your money can be increased multiple times over a period of time.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Eligible amount: BDT. 1.00 lac and multiple.</p>', '<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Under this scheme, your money can be increased multiple times over a period of time.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Eligible amount: BDT. 1.00 lac and multiple.</p>', 1, 4, NULL, NULL, '.', 1),
(3, 'Education Pension Scheme', 'For the Individuals who wants to save now to meet the future educational expenses for their children.', 1, '1598421626-12694877.jpg', '1580743257-49104481.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">For the Individuals who wants to save now to meet the future educational expenses for their children.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit on monthly installment basis.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Eligibility: 2 &ndash; 10 years of your child.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Minimum monthly deposit: BDT 3,000.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit Tenure: First 7 (seven) years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Pension Tenure: Next 7 (seven) years.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">For the Individuals who wants to save now to meet the future educational expenses for their children.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit on monthly installment basis.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Eligibility: 2 &ndash; 10 years of your child.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Minimum monthly deposit: BDT 3,000.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit Tenure: First 7 (seven) years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Pension Tenure: Next 7 (seven) years.</p>', 2, 0, NULL, NULL, '.', 1),
(4, 'Senior Citizen Term Deposit', 'Under this scheme, your money can be increased multiple times over a period of time. Eligible amount: BDT. 1.00 lac and multiple.', 1, '1598264161-85304698.jpg', '1580743257-49104481.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Under this scheme, your money can be increased multiple times over a period of time. Eligible amount: BDT. 1.00 lac and multiple.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">This scheme is applicable only to the Senior citizens who are 59 years and above.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">They will be given 0.25% higher rate over regular prevailing FDR rate for individual.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Under this scheme, your money can be increased multiple times over a period of time. Eligible amount: BDT. 1.00 lac and multiple.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">This scheme is applicable only to the Senior citizens who are 59 years and above.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">They will be given 0.25% higher rate over regular prevailing FDR rate for individual.</p>', 1, 2, NULL, NULL, '.', 1),
(5, 'Mohila Savings Scheme', 'Exclusively for female customers for maximizing their savings and ensuring higher return on their investments.', 1, 'Mohila Saving Scheme.jpg', '1598442465-94644399.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Exclusively for female customers for maximizing their savings and ensuring higher return on their investments.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit on monthly installment basis.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Competitive rate of return and highest level of safety.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Eligibility: Minimum age - 18 years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Minimum monthly deposit amount BDT 2,000/-</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Tenure: 3, 5, 8, 10 &amp; 12 years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Amount will be calculating BDT 2,000/- multiple.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Exclusively for female customers for maximizing their savings and ensuring higher return on their investments.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Deposit on monthly installment basis.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Competitive rate of return and highest level of safety.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Eligibility: Minimum age - 18 years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Minimum monthly deposit amount BDT 2,000/-</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Tenure: 3, 5, 8, 10 &amp; 12 years.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Amount will be calculating BDT 2,000/- multiple.</p>', 2, 0, NULL, NULL, '.', 1),
(6, 'Term Deposit', 'NHFIL receives Fixed Term Deposits for 3, 4, 5, 6, 9, 12, 13, 15, 24 & 36 months with the option of auto renewal at the competitive interest rate to be given at maturity.', 1, '1598421218-89145578.jpg', 'main-qimg-c6c9f2ccebdb4d6c368f0be1950f4133.jpeg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">NHFIL receives Fixed Term Deposits for 3, 4, 5, 6, 9, 12, 13, 15, 24 &amp; 36 months with the option of auto renewal at the competitive interest rate to be given at maturity.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Minimum Deposit Amount: BDT 50,000/- &amp; above.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">NHFIL receives Fixed Term Deposits for 3, 4, 5, 6, 9, 12, 13, 15, 24 &amp; 36 months with the option of auto renewal at the competitive interest rate to be given at maturity.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Minimum Deposit Amount: BDT 50,000/- &amp; above.</p>', 1, 1, NULL, NULL, '.', 1),
(7, 'Monthly Savings Scheme (MSS)', 'NHFIL has introduced Monthly Savings Scheme for the depositors. It caters to the specific concerns of you and provides an invaluable opportunity of securing life in future.', 1, '1598420777-6338012.jpg', '22910-savings3-pixabay.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">NHFIL Monthly Savings Deposit gives you the opportunity to save your money for better life in future.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Tenure 2, 3, 5, 7 &amp; 10 years</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Scheme amount BDT 500/- multiple but minimum deposit amount will be BDT 1,000/-</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">NHFIL Monthly Savings Deposit gives you the opportunity to save your money for better life in future.</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Tenure 2, 3, 5, 7 &amp; 10 years</p>\r\n<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Scheme amount BDT 500/- multiple but minimum deposit amount will be BDT 1,000/-</p>', 2, 0, NULL, NULL, '.', 1),
(8, 'Periodical Income Scheme', 'National Housing Periodical Income Scheme is a unique deposit product for anyone who can receive profit on monthly, quarterly, half yearly & yearly basis on his/her deposited amount to be kept for a fixed term.', 1, '1598418202-36019329.jpg', '1598250183-71626103.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">National Housing Periodical Income Scheme is a unique deposit product for anyone who can receive profit on monthly, quarterly, half yearly &amp; yearly basis on his/her deposited amount to be kept for a fixed term.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Minimum Deposit BDT 100,000.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Profit will be paid on monthly, quarterly, half yearly &amp; yearly basis.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Renewal option at prevailing rate.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Tenure 1 to 5 years.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">National Housing Periodical Income Scheme is a unique deposit product for anyone who can receive profit on monthly, quarterly, half yearly &amp; yearly basis on his/her deposited amount to be kept for a fixed term.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Minimum Deposit BDT 100,000.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Profit will be paid on monthly, quarterly, half yearly &amp; yearly basis.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Renewal option at prevailing rate.</p>\r\n<p class=\"MsoNormal\" style=\"text-indent: .5in;\">Tenure 1 to 5 years.</p>', 1, 3, NULL, NULL, '', 1),
(9, 'Millionaire Scheme', 'NHFIL Millionaire Scheme is a deposit product for becoming millionaire after a certain time of period with the monthly flexible savings for best suitable tenure.', 1, '1598420307-48815511.jpg', 'slider2.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">NHFIL Millionaire Scheme is a deposit product for becoming millionaire after a certain time of period with the monthly flexible savings for best suitable tenure.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">NHFIL Millionaire Scheme is a deposit product for becoming millionaire after a certain time of period with the monthly flexible savings for best suitable tenure.</p>', 2, 0, NULL, NULL, '', 1),
(10, 'National Housing Kotipoti Scheme', 'Anyone can get the facility for becoming Kotipoti by opening a kotipoti scheme with NHFIL. Under this scheme, you will be the owner of BDT 1.00 (one) crore after certain period with your affordable monthly savings.', 1, 'getty_845452938_405983.jpg', 'slider2.jpg', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Anyone can get the facility for becoming Kotipoti by opening a kotipoti scheme with NHFIL. Under this scheme, you will be the owner of BDT 1.00 (one) crore after certain period with your affordable monthly savings.</p>', '<p class=\"MsoNormal\" style=\"margin-left: .5in;\">Anyone can get the facility for becoming Kotipoti by opening a kotipoti scheme with NHFIL. Under this scheme, you will be the owner of BDT 1.00 (one) crore after certain period with your affordable monthly savings.</p>', 2, 0, NULL, NULL, '', 1);
