INSERT INTO `vmsl_email_template` (`id`, `category`, `template`, `subject`, `header`, `body`, `footer`, `add1`, `created_at`, `date`, `status`) VALUES
(1, 1, 'Date:', 'Job offer from Bangladesh Infrastructure Finance Fund Limited (BIFFL)', 'Dear,', '<p><span style=\"color: #222222; font-family: Arial, Helvetica, sans-serif; font-size: small;\">Congratulations! This email is to formally offer you the job of job</span><span style=\"color: #222222; font-family: Arial, Helvetica, sans-serif; font-size: small;\">&nbsp;for Bangladesh Infrastructure Finance Fund Limited (BIFFL). We strongly believe that your skills and expertise will help our company to reach great heights. As discussed with you previously, you must start on {{ $data[\'date\'] }}, and the salary stands at [salary figure] per annum. We have the policy to disburse the salary by every 10th of every month, and it will be credited directly to your bank account. You are supposed to report to [reporting manager] on [day] at sharp [time]. The pension scheme offered by the organization covers your entire family, and it will begin one month from your first working day. You may sign up for additional benefits that the company provides [can include other benefits as negotiated with the candidate].</span></p>', '<p><strong>Regards,</strong></p>\r\n<p>Bangladesh Infrastructure Finance Fund Limited (BIFFL)</p>\r\n<p><strong>Address:&nbsp;</strong>Borak Unique Heights, Level-3, 117 Kazi Nazrul Islam Avenue, Eskaton Garden, Dhaka-1217, Bangladesh.</p>\r\n<p><strong>Phone:</strong> +880-2-8333238-9</p>\r\n<p><strong>Email:</strong> info@biffl.com</p>', 'Time:', 'Position For:', '2022-09-21 11:23:50', 1),
(2, 2, 'Date:', 'Job offer from Bangladesh Infrastructure Finance Fund Limited (BIFFL)', 'Dear,', '<p>Congratulations! This email is to formally offer you the job of job&lt;/span&gt;&lt;span style=\"color: #222222; font-family: Arial, Helvetica, sans-serif; font-size: small;\"&gt;&amp;nbsp;for Bangladesh Infrastructure Finance Fund Limited (BIFFL). We strongly believe that your skills and expertise will help our company to reach great heights. As discussed with you previously, you must start on {{ $data[\'date\'] }}, and the salary stands at [salary figure] per annum. We have the policy to disburse the salary by every 10th of every month, and it will be credited directly to your bank account. You are supposed to report to [reporting manager] on [day] at sharp [time]. The pension scheme offered by the organization covers your entire family, and it will begin one month from your first working day. You may sign up for additional benefits that the company provides [can include other benefits as negotiated with the candidate]</p>', '<p><strong>Regards,</strong></p>\r\n<p>Bangladesh Infrastructure Finance Fund Limited (BIFFL)</p>\r\n<p><strong>Address:&nbsp;</strong>Borak Unique Heights, Level-3, 117 Kazi Nazrul Islam Avenue, Eskaton Garden, Dhaka-1217, Bangladesh.</p>\r\n<p><strong>Phone:</strong>&nbsp;+880-2-8333238-9</p>\r\n<p><strong>Email:</strong>&nbsp;info@biffl.com</p>\r\n<p>&nbsp;</p>', 'Time:', 'Position For:', '2022-09-21 11:23:50', 1),
(3, 3, 'Date:', 'Job offer from Bangladesh Infrastructure Finance Fund Limited (BIFFL)', 'Dear,', '<p>Congratulations! This email is to formally offer you the job of job&lt;/span&gt;&lt;span style=\"color: #222222; font-family: Arial, Helvetica, sans-serif; font-size: small;\"&gt;&amp;nbsp;for Bangladesh Infrastructure Finance Fund Limited (BIFFL). We strongly believe that your skills and expertise will help our company to reach great heights. As discussed with you previously, you must start on {{ $data[\'date\'] }}, and the salary stands at [salary figure] per annum. We have the policy to disburse the salary by every 10th of every month, and it will be credited directly to your bank account. You are supposed to report to [reporting manager] on [day] at sharp [time]. The pension scheme offered by the organization covers your entire family, and it will begin one month from your first working day. You may sign up for additional benefits that the company provides [can include other benefits as negotiated with the candidate]</p>', '<p><strong>Regards,</strong></p>\r\n<p>Bangladesh Infrastructure Finance Fund Limited (BIFFL)</p>\r\n<p><strong>Address:</strong> Borak Unique Heights, Level-3, 117 Kazi Nazrul Islam Avenue, Eskaton Garden, Dhaka-1217, Bangladesh.</p>\r\n<p><strong>Phone:</strong>&nbsp;+880-2-8333238-9</p>\r\n<p><strong>Email:</strong>&nbsp;info@biffl.com</p>\r\n<p>&nbsp;</p>', 'Time:', 'Position For:', '2022-09-21 11:23:50', 1);
