INSERT INTO `vmsl_headline` (`id`, `title`, `description`, `slug`, `category`, `status`, `add_info1`, `created_at`) VALUES
(1, '0', 'On May 2023, BIFFL signed Subsidiary Loan Agreement with the Finance Division, MoF for ‘Energy Efficiency in the Industry project funded by KfW.', NULL, NULL, 1, NULL, '2022-09-15 18:38:32'),
(2, '0', 'BIFFL signed a ‘Separate Agreement’ with KfW for the implementation of the Energy Efficiency in the Industry (EEI) project on December 2022.', NULL, NULL, 2, NULL, '2022-09-15 18:38:43'),
(3, '0', 'On December 2022, a contract for the consultant’s services of the Food Value Chain Improvement Project was signed.', NULL, NULL, 2, NULL, '2022-09-15 18:39:23');
INSERT INTO `vmsl_loan` (`id`, `name`, `category`, `short_description`, `show_home_page`, `priority`, `icon`, `about`, `types_loan`, `feature`, `status`, `eligibility`, `interest_rate`) VALUES
(5, 'EECPFP PHASE-II', 1, '<p style=\"text-align: justify;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12px; font-weight: 400; white-space: pre-wrap;\"><span style=\"font-size: 12pt;\">From the &ldquo;Energy Efficiency and Conservation Promotion Financing Project&rdquo; (EECPFP) under the Loan Agreement No. BD-P90 included in the 37th Japanese ODA loan package, dated June 2016 between Japan and Bangladesh, a total loan of JPY11,988 million (USD95 million approximately) is available for BIFFL, shared with IDCOL. In addition, BIFFL has also received JPY574 million (approximately USD5.50 million) as technical assistance. This facility can be used for 9 years.</span></span></strong></p>\r\n<h2 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 15px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 26px; line-height: 34px; font-family: Habibi; text-transform: uppercase; color: #444444; text-align: left;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">OBJECTIVE</strong></h2>\r\n<p style=\"text-align: justify;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12px; font-weight: 400; white-space: pre-wrap;\"><span style=\"font-size: 12pt;\">Energy Efficiency &amp; Conservation Promotion Financing Project(EECPHP) aims to encourage the penetration of EE&amp;C technology, machinery, and equipment in Bangladesh, so as to contribute to the development of a sustainable society where power demand-supply balance is well under control. It is also expected to contribute to the reduction of greenhouse effect gas emissions.</span></span></strong></p>\r\n<p style=\"text-align: justify;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12px; font-weight: 400; white-space: pre-wrap;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"../../uploads/images/criteria-category-diagram.jpeg\" width=\"680\" height=\"359\" /></span></strong></p>\r\n<p style=\"text-align: justify;\">&nbsp;&nbsp;</p>', 1, 1, 'criteria-category-diagram.jpeg', 'hands-holding-small-tree-to-be-planted-free-photo.jpg', '<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\" border=\"1\" width=\"100%\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\" width=\"25%\">Step1:<br style=\"box-sizing: border-box;\" />Contact BIFFL</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\" width=\"75%\">An aspiring applicant may visit the EE&amp;C Finance team at the BIFFL office to discuss initial&nbsp;eligibility for the loan.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\">Step2:<br style=\"box-sizing: border-box;\" />Get Application</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\">Once BIFFL officials confirm the potentiality the applicant will be handed over an application&nbsp;form and a checklist of required documents.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\">Step3:<br style=\"box-sizing: border-box;\" />Submission of the Application and<br style=\"box-sizing: border-box;\" />Preliminary Review by BIFFL</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\">Upon submission of the filled-in application form along with the required documents, the BIFFL&nbsp;officials will review the documents and visit the project site. The applicant may be requested to&nbsp;re-submit some documents if any changes need to be made.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\">Step4:<br style=\"box-sizing: border-box;\" />Review by SREDA</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\">Once BIFFL finds the project eligible for funding, BIFFL will forward the file to SREDA for&nbsp;evaluation of technical eligibility.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\">Step5:<br style=\"box-sizing: border-box;\" />Final Review by BIFFL</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\">BIFFL, upon receiving NOC from SREDA, will perform a financial evaluation and other due&nbsp;diligence by reviewing the submitted documents and other information as deemed&nbsp;necessary</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\">Step6:<br style=\"box-sizing: border-box;\" />Approval of the Loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\">Once BIFFL is satisfied with the project evaluation and upon confirmation of social and&nbsp;environmental compliance with the loan proposal submitted by the applicant, BIFFL management&nbsp;will approve the loan proposal and issue a sanction letter.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #548235; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #ffffff; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" align=\"right\" valign=\"middle\">Step7:<br style=\"box-sizing: border-box;\" />Disbursement of the Loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: #e2f0d9; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; color: #000000; text-align: justify;\" align=\"left\" valign=\"middle\">Upon acceptance of the sanction letter, loan documentation will be executed &amp; disbursement&nbsp;of the loan will be made by BIFFL in favor of the applying company.</td>\r\n</tr>\r\n</tbody>\r\n</table>', '<h2 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 15px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 26px; line-height: 34px; font-family: Habibi; text-transform: uppercase; color: #444444; text-align: left;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">FEATURES OF THE LOAN</strong></h2>\r\n<p>&nbsp;</p>\r\n<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\" border=\"1\" width=\"100%\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 1px 1px 0px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial #e5e5e5 rgba(0, 0, 0, 0.1) initial; border-style: initial solid solid initial;\" align=\"left\" valign=\"middle\" width=\"19%\">Eligibility</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; text-align: justify;\" align=\"left\" valign=\"middle\" width=\"81%\">See the List of Eligible Technology and Equipment (Eligibility criteria may change without prior notification)</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 1px 1px 0px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial #e5e5e5 rgba(0, 0, 0, 0.1) initial; border-style: initial solid solid initial;\" align=\"left\" valign=\"middle\">Amount Threshold</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; text-align: justify;\" align=\"left\" valign=\"middle\">The maximum amount for a single project loan application is BDT 1.5 billion. The minimum amount for a single project loan application is temporarily set at BDT 5 million.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 1px 1px 0px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial #e5e5e5 rgba(0, 0, 0, 0.1) initial; border-style: initial solid solid initial;\" align=\"left\" valign=\"middle\">Interest Rate</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; text-align: justify;\" align=\"left\" valign=\"middle\">The standard (minimum) interest rate for the loan is 5-6%. BIFFL may suggest otherwise depending on the financial appraisal result.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 1px 1px 0px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial #e5e5e5 rgba(0, 0, 0, 0.1) initial; border-style: initial solid solid initial;\" align=\"left\" valign=\"middle\">Tenure of loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; text-align: justify;\" align=\"left\" valign=\"middle\">The tenure of the loan is set depending on the nature of the projects. BIFFL shall conduct a financial analysis to identify the appropriate tenure for each individual project loan, to be agreed upon with the project owner/promoter.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 1px 1px 0px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial #e5e5e5 rgba(0, 0, 0, 0.1) initial; border-style: initial solid solid initial;\" align=\"left\" valign=\"middle\">Grace Period</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; text-align: justify;\" align=\"left\" valign=\"middle\">BIFFL may grant a grace period for the loan, with respect to the nature of the projects.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 1px 1px 0px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial #e5e5e5 rgba(0, 0, 0, 0.1) initial; border-style: initial solid solid initial;\" align=\"left\" valign=\"middle\">Availability of the Loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; text-align: justify;\" align=\"left\" valign=\"middle\">This loan will be provided on a first come first serve basis depending on the merits of individual cases.</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<h2 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 15px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 26px; line-height: 34px; font-family: Habibi; text-transform: uppercase; color: #444444; text-align: left;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">LOAN ADMINISTRATION STRUCTURE</strong></h2>\r\n<p><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 18px; font-weight: 400; text-transform: uppercase;\">THE ORIGINAL FUND IS THE CONCESSIONAL LOAN EXTENDED FROM THE GOVERNMENT OF JAPAN (JICA) TO THE GOVERNMENT OF BANGLADESH (MINISTRY OF FINANCE).</span></strong></p>\r\n<p>&nbsp;<img src=\"../../uploads/images/administation_lone-1.jpg\" width=\"1328\" height=\"698\" /></p>', 1, 'JICA-4-Fold-Leaflet-Technology-Requirements.pdf', 'eecphp-phase-II'),
(11, 'EEREWEF', 2, '<p style=\"text-align: justify;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px; font-weight: 400;\">On 12 August 2021, The GoB and AFD signed a loan agreement under which BIFFL is receiving EUR50 million for 15 years to finance energy efficiency, renewable energy, and women entrepreneurship development-related areas. This amount is also supplemented with a technical assistance fund. Under this project, BIFFL will provide long-term concessional loans to the stated areas. The project is currently under implementation. </span></strong></p>\r\n<h2 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 15px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 26px; line-height: 34px; font-family: Habibi; text-transform: uppercase; color: #444444;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">OBJECTIVE&nbsp;</strong></h2>\r\n<p style=\"text-align: justify;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\"><span style=\"color: #444444; font-family: \'PT Sans\'; font-size: 16px; font-weight: 400;\">The EUR 50 million project funded by the Agence Fran&ccedil;aise de D&eacute;veloppement (AFD) and implemented by Bangladesh Infrastructure Finance Fund Limited (BIFFL) aims to support the Government of Bangladesh&rsquo;s aim to reduce energy intensity by 20% within 2030. It is also aimed at bringing about equitable growth through support to women entrepreneurs.</span></strong></p>', 1, 2, 'istockphoto-1170425284-612x612-1.jpg', '2018-01-30-2.jpg', '<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; width: 1140px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step1:<br style=\"box-sizing: border-box;\" />Contact BIFFL</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">An aspiring applicant may visit the EEREWEF Finance team at the BIFFL office to discuss initial eligibility for the loan.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step2:<br style=\"box-sizing: border-box;\" />Fill out the Application Form</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Once BIFFL officials confirm the potentiality the applicant will be handed over an application form and a checklist of required documents.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step3:<br style=\"box-sizing: border-box;\" />Submit Application with Required Documents</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Upon submission of the filled-in application form along with the required documents, the BIFFL officials will review the documents and visit the project site. The applicant may be requested to re-submit some documents if any changes need to be made.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step4:<br style=\"box-sizing: border-box;\" />Review by BIFFL</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Once BIFFL finds the project eligible for funding, BIFFL will forward the file to AFD for evaluation of technical eligibility.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step5:<br style=\"box-sizing: border-box;\" />Review by AFD</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">BIFFL, upon receiving NOC from AFD, will perform financial evaluation and other due diligence through reviewing the submitted documents and other information as deemed necessary</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step6:<br style=\"box-sizing: border-box;\" />Approval of the Loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Once BIFFL is satisfied with the project evaluation and upon confirmation of social and environmental compliance of the loan proposal submitted by the applicant, BIFFL management will approve the loan proposal and issue a sanction letter.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Step7:<br style=\"box-sizing: border-box;\" />Disbursement of the Loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Upon acceptance of the sanction letter, loan documentation will be executed &amp; disbursement of the loan will be made by BIFFL in favor of the applying company</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p class=\"MsoNormal\">&nbsp;</p>', '<p><strong>FEATURES OF THE LOAN</strong></p>\r\n<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; width: 639px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px; height: 148px;\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 357.443px;\">Amount</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 281.548px;\">Up to BDT 100 crore</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 357.443px;\">Interest Rate (Terms &amp; Conditions Apply)</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 281.548px;\">Attractive concessional rate</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 357.443px;\">Tenure</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 281.548px;\">Flexible (greater than 3 years)</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 357.443px;\">Grace Period</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; width: 281.548px;\">\r\n<p>Flexible</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p>&nbsp;</p>\r\n<h2 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 15px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 26px; line-height: 34px; font-family: Habibi; text-transform: uppercase; color: #444444;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">CRITERIA FOR ELIGIBILITY</strong></h2>\r\n<p>&nbsp;</p>\r\n<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; width: 1140px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Criteria</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Technical</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Other</strong></td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Energy Efficiency</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">20% energy savings</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Equipment only</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Renewable Energy</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Solar, wind, hydro, bio etc.</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Equipment &amp; other items</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Women Entrepreneurship</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">&ndash;</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Women-owned</td>\r\n</tr>\r\n</tbody>\r\n</table>', 1, NULL, 'eerewef-loan'),
(13, 'Home Financing Scheme', 5, '<p>Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.</p>', 0, 0, 'homeloan.jpg', 'hlb-hk-term-loan-banner.jpg', '<p><br></p>', '<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Calibri\',\'sans-serif\'; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">We value our expatriates by providing total care for building their dream home here. With us, you can buy/build your dream home at ease.</span></p>', 1, 'BIFFL - Copy.pdf', 'home-financing-schem');
INSERT INTO `vmsl_loan` (`id`, `name`, `category`, `short_description`, `show_home_page`, `priority`, `icon`, `about`, `types_loan`, `feature`, `status`, `eligibility`, `interest_rate`) VALUES
(14, 'Renovation Loan', 5, 'NHFIL helps you to decorate your own apartment or house with modern facilities. \"Renovation\" Loan will support you to improve the facilities of existing apartment or house.', 1, 0, 'Personal-loan_500-x-310.jpg', 'hlb-hk-term-loan-banner.jpg', '<p><br></p>', '<p><span style=\"font-size: 11.0pt; line-height: 107%; font-family: \'Calibri\',\'sans-serif\'; mso-ascii-theme-font: minor-latin; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-hansi-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-bidi-theme-font: minor-bidi; mso-ansi-language: EN-US; mso-fareast-language: EN-US; mso-bidi-language: AR-SA;\">Making the right repairs or upgrades to your house can often be a wise investment, adding considerably to its value as well as comfort, looks, and style. If you&rsquo;re looking for financing to cover your home renovation or repair costs, National Housing is always by your side.</span></p>', 1, 'BIFFL - Copy.pdf', 'asd'),
(15, 'Housing Plot Purchase', 5, NULL, 0, 0, 'loan 2.jpg', 'bhfl_hlbt-banners_desktop_1349x245px.jpg', '<p><br></p>', '<p class=\"MsoNormal\" style=\"text-align: justify;\">National Housing provide loans to buy the plot of your choice. With us unlock your freedom of building a space that is uniquely yours. Buy the land of your choice and start turning your dream home into reality.</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">For the construction of residential premise, National Housing provides loan for purchase of residential plot in an urban area.</p>', 1, 'BIFFL - Copy.pdf', 'adsf'),
(27, 'FVCIP', 6, '<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; text-align: justify;\">The &ldquo;Food Value Chain Improvement Project&rdquo; (FVCIP) is another JICA-funded project under Loan Agreement No. BD-P115 is included in the 41st ODA Loan package of the Japan Government. BIFFL is the sole implementing agency of this project. This project aims to facilitate access to credit for agribusiness and food processing industries to in turn enhance the quality and productivity of end products by providing concessional loans (total loan amount JPY11,218 million). Like other projects of JICA, this project also includes technical assistance for the capacity development of BIFFL as well as the food processing and value chain sector.</p>\r\n<h4 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 22px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 20px; line-height: 30px; font-family: Habibi; text-transform: uppercase; color: #444444; text-align: left;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">PROJECT OBJECTIVE</strong></h4>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; text-align: justify;\">The objective of the Project is to improve credit access for agribusiness and food processing industries and promote a higher value of processed food products, thereby contributing to the enhancement of competitiveness of agribusiness and food processing industries through the improvement of the food value chain in Bangladesh.</p>\r\n<h4 style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 22px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-weight: normal; font-stretch: normal; font-size: 20px; line-height: 30px; font-family: Habibi; text-transform: uppercase; color: #444444; text-align: left;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">PROJECT OUTLINE</strong></h4>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; text-align: justify;\">The project approaches the achievement of its objectives from two angles: 1) provision of two-step loan (TSL) as concessional financing to agribusiness and food processing industries; and 2) provision of capacity building to agribusiness and food processing industries.</p>', 1, 5, 'equity_bg - Copy.jpg', '2018-01-30-2.jpg', '<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Lender</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">BIFFL</strong></td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Borrower</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\">Any business or company meeting the eligibility criteria of the Project</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Currency</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\">Bangladeshi Taka (BDT)</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Amount</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\">Maximum BDT 500,000,000</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Term</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\">Long term loans: Up to 10 years&nbsp;\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: 26px; margin: 0px 0px 10px !important 0px;\">&nbsp;</p>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; line-height: 26px; margin: 0px 0px 10px !important 0px;\">Medium term loans: Up to 5 years</p>\r\n</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Interest rate</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\">Not exceeding 6%</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"160\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Repayment, Security and other terms</strong></td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\" width=\"445\">To be determined by agreement between BIFFL and End-Borrowers in compliance with the rules and regulations in Bangladesh</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"font-size: 14pt; color: #00652e;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">To learn more, please go through these documents:</strong></span></p>\r\n<p><span style=\"font-size: 14pt; color: #008000;\"><strong><span style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, \'Noto Sans\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\';\"><a title=\"General Brochure\" href=\"../../uploads/images/gallery/General-Brochure.pdf\" target=\"_blank\" rel=\"noopener\">General Brochure</a></span></strong></span></p>\r\n<p><span style=\"font-size: 14pt; color: #008000;\"><strong><span style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, \'Noto Sans\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\';\"><a title=\"Loan-Brochure\" href=\"../../uploads/images/gallery/Loan-Brochure.pdf\" target=\"_blank\" rel=\"noopener\">Loan Brochure</a></span></strong></span></p>\r\n<p><span style=\"font-size: 14pt; color: #008000;\"><strong><span style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, \'Noto Sans\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\';\"><a title=\"Eligibility of Borrowers\" href=\"../../uploads/images/gallery/Eligibility-of-Borrowers.pdf\" target=\"_blank\" rel=\"noopener\">Eligibility of Borrowers</a></span></strong></span></p>\r\n<p><span style=\"font-size: 14pt; color: #008000;\"><strong><span style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, \'Noto Sans\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\';\"><a title=\"Application Procedure for Loans\" href=\"../../uploads/images/gallery/Application-Procedure-for-Loans.pdf\" target=\"_blank\" rel=\"noopener\">Application Procedure for Loans</a></span></strong></span></p>\r\n<p><span style=\"font-size: 14pt; color: #008000;\"><strong><span style=\"font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', Roboto, \'Helvetica Neue\', Arial, \'Noto Sans\', sans-serif, \'Apple Color Emoji\', \'Segoe UI Emoji\', \'Segoe UI Symbol\', \'Noto Color Emoji\';\"><a title=\"Credit Application Booklet\" href=\"../../uploads/images/gallery/BIFFL-Credit-Application-booklet-_FVCIP.vnd.openxmlformats-officedocument.wordprocessingml.document\">Credit Application Booklet</a></span></strong></span></p>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; margin: 0px 0px 10px !important 0px;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Contact Information:</strong></p>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; margin: 0px 0px 10px !important 0px;\">Hotline: +88 01844 221669</p>\r\n<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-variant-alternates: normal; font-kerning: auto; font-optical-sizing: auto; font-feature-settings: normal; font-variation-settings: normal; font-variant-position: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; margin: 0px 0px 10px !important 0px;\">Email: fvcip@biffl.org.bd</p>', NULL, 1, '1General-Brochure.pdf', 'fvicp'),
(28, 'FEATURES OF THE LOAN', 7, NULL, 1, 8, 'financial_bg - Copy.jpg', '2018-01-30-2.jpg', NULL, '<table style=\"margin: 0px 0px 21px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; border-collapse: collapse; border-spacing: 0px; position: relative; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<tbody style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Eligibility</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">See the List of Eligible Technology and Equipment<br style=\"box-sizing: border-box;\" />(Eligibility criteria may change without prior notification)</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Amount<br style=\"box-sizing: border-box;\" />Threshold</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Maximum amount for a single project loan application is BDT 1 billion.<br style=\"box-sizing: border-box;\" />Minimum amount for a single project loan application is temporarily set at BDT 5 million.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Interest Rate</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Standard (minimum) interest rate for the loan is 4%. BIFFL may suggest otherwise<br style=\"box-sizing: border-box;\" />depending on the financial appraisal result.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Tenure of loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Tenure of loan is set depending on the nature of the projects. BIFFL shall conduct<br style=\"box-sizing: border-box;\" />financial analysis to identify the appropriate tenure for each individual project loans, to be<br style=\"box-sizing: border-box;\" />agreed with the project owner/promoter.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Grace Period</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">BIFFL may grant grace period for the loan, with respect to the nature of the projects.</td>\r\n</tr>\r\n<tr style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent; position: relative;\">\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">Availability of<br style=\"box-sizing: border-box;\" />the Loan</td>\r\n<td style=\"box-sizing: border-box; margin: 0px; padding: 10px; border-width: 0px 0px 1px; border-image: initial; outline: 0px; vertical-align: top; background: transparent; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; position: relative; border-color: initial initial rgba(0, 0, 0, 0.1) initial; border-style: initial initial solid initial;\">This loan will be provided on first come first serve basis depending on the merits of<br style=\"box-sizing: border-box;\" />individual cases.</td>\r\n</tr>\r\n</tbody>\r\n</table>', 1, NULL, 'features-of-the-loan'),
(29, 'EEI', 8, '<p class=\"MsoNormal\" style=\"text-align: justify;\">In 2022, the Government of People&rsquo;s Republic of Bangladesh (GoB) and Kreditanstalt f&uuml;r Wiederaufbau (KfW), the German state-owned development bank, signed a loan agreement of up to EUR 80 million along with a grant agreement of up to EUR 2 million to implement the project &lsquo;Energy Efficiency in the Industry (EEI)&rsquo;. GoB will channel a loan portion of up to EUR 40 million and a grant portion of up to EUR 1 million to BIFFL, one of the project-executing agencies, for implementation of this project.</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">The purpose of the project is to extend refinancing facility of sub-loans to industrial companies, including Small and Medium Enterprises (SMEs), for investment in energy efficient extensions and/or replacements of equipment and machinery as well as production processes which shall, in each case, realize a final energy consumption and associated CO2 reduction by at least 20%. As such, this project will contribute to an economically, ecologically, and socially sustainable use of energy in Bangladesh.</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">The grant portion will be used for the expert services that will help ensure capacity building and pipeline development of BIFFL, conducting eligibility assessments and monitoring of sub-loans and supporting BIFFL in maintaining Environmental and Social (E&amp;S) requirements.</p>', NULL, 90, 'istockphoto-1170425284-612x612-1.jpg', '2018-01-30-2.jpg', NULL, NULL, 1, NULL, 'eei');
