INSERT INTO `vmsl_portfolios` (`id`, `title`, `image`, `category`, `serial_number`, `description`, `gallery`, `status`, `add1`, `created_at`, `updated_at`) VALUES
(1, 'Bangladesh owned by the  Government of Bangladesh and represented by Finance Division of Ministry of Finance.', '1.jpg', 1, 1, 'S M Anisuzzaman has joined as the Chief Executive Officer of Bangladesh Infrastructure Finance Fund Limited, one of the biggest Non Bank Financial Institutions in Bangladesh owned by the  Government of Bangladesh and represented by Finance Division of Ministry of Finance. Prior to this appointment, he was the Deputy Managing Director of National Housing Finance and Investments Limited.', NULL, 1, NULL, '2022-08-29 07:14:36', '2022-08-29 07:14:36'),
(2, 'He has completed his BSc in Civil Engineering from BUET', '9.jpg', 2, 2, 'He has completed his BSc in Civil Engineering from BUET and MBA in Strategic and International Management from the University of Dhaka. He has traveled widely in many countries around the globe.', NULL, 1, NULL, '2022-08-29 07:15:12', '2022-08-29 07:15:12');
