INSERT INTO `vmsl_services` (`id`, `title`, `image`, `banner`, `short_description`, `description`, `status`, `created_at`, `updated_at`, `add_info1`, `add_info2`) VALUES
(1, 'Area of Investment', 'large_inf_bg1.jpg', 'large_inf_bg.jpg', 'Infrastructure, Energy Efficiency, Renewable Energy, Waste Management, Food & Agricultural Processing and Value Chain, Women Entrepreneurship', '<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\">&nbsp;</pre>\r\n<ol style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 1rem; color: #363636; font-family: Roboto, sans-serif; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Infrastructure</span></pre>\r\n<ol style=\"box-sizing: border-box; margin-top: 0px; margin-bottom: 0px; list-style-type: lower-alpha;\">\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Power and Energy</span></li>\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Connectivity &amp; Communication </span></li>\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Industrial Infrastructure Projects including Economic Zones</span></li>\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box; text-align: justify;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Tourism Infrastructure</span></li>\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Natural Resource, Environmental &amp; Social Infrastructure</span></li>\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box;\"><span style=\"font-family: Roboto; font-size: 12pt; color: #212529; text-align: justify;\">Urban &amp; Rural Development Projects</span></li>\r\n<li class=\"MsoNormal\" style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">IT and IT Infrastructure Projects </span></pre>\r\n</li>\r\n</ol>\r\n</li>\r\n<li style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Energy Efficiency</span></pre>\r\n</li>\r\n<li style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Renewable Energy</span></pre>\r\n</li>\r\n<li style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Waste Management</span></pre>\r\n</li>\r\n<li style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Food &amp; Agricultural Processing and Value Chain</span></pre>\r\n</li>\r\n<li style=\"box-sizing: border-box;\">\r\n<pre style=\"box-sizing: border-box; font-family: SFMono-Regular, Menlo, Monaco, Consolas, \'Liberation Mono\', \'Courier New\', monospace; font-size: 14px; margin-top: 0px; margin-bottom: 1rem; overflow: auto; color: #212529;\"><span style=\"box-sizing: border-box; font-family: Roboto !important; font-size: 12pt; line-height: 14pt;\">Women Entrepreneurship</span></pre>\r\n</li>\r\n</ol>', 2, '2022-09-14 12:25:17', '2022-09-14 12:25:17', 'infrastructure-sectors', NULL),
(2, 'Loan Products', 'loan_bg - Copy.jpg', 'loan_bg.jpg', 'Term Loan, Working capital loan, Bridge financing, Factoring, Take over financing, Take out financing, Lease financing, Bond financing, Commercial, paper/instrument', '<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Term Loan</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Working capital loan</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Bridge financing</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Factoring</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Take over financing</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Take out financing</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Lease financing</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Bond financing</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Commercial paper/instrument</li>\r\n</ul>', 2, '2022-09-14 13:24:59', '2022-09-14 13:24:59', 'loan-products', NULL),
(3, 'Equity/Hybrid Products', 'equity_bg - Copy.jpg', 'equity_bg.jpg', 'Ordinary Shares, Preference Shares, Mezzanine financing, Convertible debt.', '<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Ordinary Shares</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Preference Shares</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Mezzanine financing</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Convertible debt</li>\r\n</ul>', 2, '2022-09-14 13:28:28', '2022-09-14 13:28:28', 'equity-hybrid-products', NULL),
(4, 'Investment Criteria and Parameters', 'limits_bg - Copy.jpg', 'limits_bg.jpg', 'In order to be eligible for funding from BIFFL, a project shall meet the following eligibility criteria:', '<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">BIFFL shall consider only those projects for financing which will withstand the viability test from the commercial and socio-economic viewpoints. Viable projects may also include those projects that will become viable after receiving &ldquo;Viability Gap Financing (VGF)&rdquo; from the Ministry of Finance, Government of the People&rsquo;s Republic of Bangladesh, as per approved &ldquo;Guidelines of Viability Gap Financing for PPP Projects&rdquo;;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Subject to the availability of fund and the provision of clause 2.11.2 (iii), BIFFL will lend up to 40 percent of the total project cost or US$ 100 million whichever is lower for a single project..</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Any &ldquo;For-Profit&rdquo; or &ldquo;Not-For-Profit&rdquo; entity legally registered in Bangladesh or abroad at the time of submission of proposal(s) in response to Request for Qualification (RFQ) or Unsolicited Proposal(s) will be eligible to apply for BIFFL financing. However, at the time of contract signing, the foreign entity is required to be registered as a legal entity in Bangladesh;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">The project shall be implemented (i.e. developed, financed and operated for the project term) by a:</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">i. Public Sector Company,</strong>&nbsp;with 51 percent or more of the subscribed and paid-up equity owned and controlled by the GoB, jointly or severally;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">ii. Private Sector Company,</strong>&nbsp;with 51 percent or more of the subscribed and paid-up equity owned and controlled by the private sector.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">A Private Sector Company</strong>&nbsp;not selected through a competitive bidding process would be eligible for direct lending by BIFFL only after the necessary statutory/ administrative approvals and clearances from relevant government agency/ authority have been obtained provided that-</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">The service to be provided by the infrastructure project is regulated and non-monopolistic in nature;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">The project is being set up under an agreement with the Government or a public sector undertaking; and</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Total lending for such private projects does not exceed 25 percent of the lending program of BIFFL in any Fiscal Year (FY).</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Projects should be an integral part of the GOB&rsquo;s priority plan for the relevant sector/sub-sectors;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">To ensure sponsor&rsquo;s commitment to the project, equity should represent not less than 20 percent of the total project cost;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Projects should meet GOB and BIFFL&rsquo;s Environmental and Social Assessment Criteria;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">(i) In evaluating an investment request, the project itself is looked at initially. Important criteria for lending would include following aspects, among others for commercial projects:</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">commercial viability;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">a sound business plan;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">a thorough appraisal report incorporating legal, technical, marketing, financial and environmental aspects</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">proven and established operational, financial and governance track record, experience and expertise of the sponsors;</li>\r\n</ul>\r\n<h2>Financing Limits</h2>\r\n<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Subject to restrictions of the Bangladesh Bank from time to time, the maximum limit of Single Borrower Exposure shall not exceed 30 (thirty) percent of BIFFL&rsquo;s equity/capital base; the maximum limit of Single group exposure shall not exceed 35 (thirty-five) percent of BIFFL&rsquo;s equity/capital base; the maximum limit of a particular sector exposure shall not exceed 50 (fifty) percent of BIFFL&rsquo;s equity/capital base.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">BIFFL shall follow a cautious lending policy of Company&rsquo;s resources &ndash; whether equity funds or borrowed money. The Company will diversify its risks by spreading its portfolio of investment to a wide variety of sectors;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">In case of Syndicated Loan, where BIFFL is not an arranger, investment by BIFFL may be equal or higher than the amount invested by the arranger/lead financier(s) of the project, subject to approval from BIFFL Board; and</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">These financial limits may be reviewed by the Board from time to time.</li>\r\n</ul>', 2, '2022-09-14 13:31:32', '2022-09-14 13:31:32', 'investment-criteria-and-parameters', NULL),
(5, 'Financing Limits', 'financial_bg - Copy.jpg', 'financial_bg.jpg', 'Subject to restrictions of the Bangladesh Bank from time to time, the maximum limit of Single Borrower Exposure shall not exceed 30 (thirty) percent of BIFFL’s equity/capital base', '<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Subject to restrictions of the Bangladesh Bank from time to time, the maximum limit of Single Borrower Exposure shall not exceed 30 (thirty) percent of BIFFL&rsquo;s equity/capital base; the maximum limit of Single group exposure shall not exceed 35 (thirty-five) percent of BIFFL&rsquo;s equity/capital base; the maximum limit of a particular sector exposure shall not exceed 50 (fifty) percent of BIFFL&rsquo;s equity/capital base.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">BIFFL shall follow a cautious lending policy of Company&rsquo;s resources &ndash; whether equity funds or borrowed money. The Company will diversify its risks by spreading its portfolio of investment to a wide variety of sectors;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">In case of Syndicated Loan, where BIFFL is not an arranger, investment by BIFFL may be equal or higher than the amount invested by the arranger/lead financier(s) of the project, subject to approval from BIFFL Board; and</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">These financial limits may be reviewed by the Board from time to time.</li>\r\n</ul>', 2, '2022-09-14 13:34:36', '2022-09-14 13:34:36', 'financing-limits', NULL),
(6, 'Investment Criteria and Parameters', 'loan_bg - Copy.jpg', 'loan_bg.jpg', 'The loan facility parameters for BIFFL have been set as under:  Priority: The project should be in line with the GOB’s priority plans for the sector.', '<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">a)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Priority:</strong>&nbsp;The project should be in line with the GOB&rsquo;s priority plans for the sector.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">b)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Procurement:</strong>&nbsp;Projects will be expected to meet BIFFL&rsquo;s requirement for International Competitive Bidding (&ldquo;ICB&rdquo;), National Competitive Bidding (&ldquo;NCB&rdquo;) or Local Competitive Bidding (&ldquo;LCB&rdquo;), as applicable. Appropriate limits for each of the process would be set out from time to time. In cases where a project is unsolicited, BIFFL may require that up to 40 percent of the total project cost or 100 percent of goods and services, whichever is less, be procured on a basis acceptable to BIFFL.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">c)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Currency:</strong>&nbsp;BIFFL will extend credit facilities in local currency. BIFFL will not offer Foreign currency loans (FCL) unless BIFFL mobilizes foreign currency funds to on-lend. Loan tenor shall not exceed the tenor for which BIFFL has raised such funds. Currency Exchange risk should be passed on to the borrower entirely. Interest rate charged to borrower should mirror the variable benchmark rate used for BIFFL&rsquo;s borrowings. Foreign currency loans may be provided only for projects which have a natural hedge by way of income in foreign currency or projects which can bear adverse exchange rate fluctuation without affecting the viability or repaying capacity.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">d)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Tenor:</strong>&nbsp;BIFFL Loan tenor and grace period will be determined considering BIFFL&rsquo;s source of finance and as per project requirements but not exceeding 15 years including a grace period not exceeding 4 years</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">e)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Interest Rate:</strong>&nbsp;Either fixed or variable rate as per customers will, reflecting current market conditions.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">f)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Equity:</strong>&nbsp;To ensure commitment, sponsors will be required to provide at least 20 percent of the project&rsquo;s equity.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">g)&nbsp;<strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">BIFFL Exposure to a project:</strong>Not exceeding 40 percent of the total project cost or US$ 100 million whichever is lower for a single project</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">h) Return on Investment and Financial Charges:</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">i. The lending rate shall conform to the prevailing rates offered by other financial institutions for long, medium and short term investments. At the same time, the management, in deciding lending rates, has to keep in mind the average cost of borrowing from various sources;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">ii. The management while fixing lending rates, in addition to the considerations given at (i) shall allow a gross average spread of 3 percent over its cost of funds;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">iii. Financial Charges as appropriate will be levied for funds disbursed or committed under the credit agreement until its execution/start of repayment by the borrower. Enhanced interest and delinquent charges would be imposed for delay in execution/start of repayment beyond the stipulated time;,</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">iv. The following fees and charges, as applicable, shall be charged to the Borrower:</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Application fee;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Due diligence fee;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Arranger&rsquo;s fee;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Delinquent/Penal Charges;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Prepayment fee.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Agency Fee</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">The fees and charges may be reviewed from time to time.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">i) Annual Volume of Financing: BIFFL will follow the investment plan prepared for the financial year and approved by the Board of Directors. This will be reviewed from time to time. The tentative investment of BIFFL for the year 2016 is BDT 1868 crore.</li>\r\n</ul>', 2, '2022-09-14 13:35:51', '2022-09-14 13:35:51', 'loan-facility-parameters', NULL),
(7, 'Projects Finance', '2017-12-16-5.jpg', 'hands-holding-small-tree-to-be-planted-free-photo.jpg', 'Project Finance is a long-term credit arrangement with a debtor related to the development and construction of infrastructure or a large commercial or industrial project. The technique involves mobilization of debt, equity, contingent equity, hedges and a variety of limited guarantees through a newly organized company, partnership or contractual joint venture, often referred to as Special Purpose Vehicle (“SPV”), for the purpose of building a capital intensive facility and operating a discrete business activity;', '<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; margin: 0px 0px 10px !important 0px;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">It Includes</strong></p>\r\n<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Lumpy capital investment;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Debt service tailored to cash flow;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Preponderance of credit enhancements ;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Extensive due diligence; and</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Involvement of several parties including sovereign entity.<br style=\"box-sizing: border-box;\" /><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Project Finance can be limited- or non-recourse transaction characterized by</strong><br style=\"box-sizing: border-box;\" />Greenfield, Born field as well as Balancing-Modernizing-Rehabilitation-Expansion Program (&ldquo;BMRE&rdquo;) projectsBIFFL can be the only financier to the project (Sole Finance)BIFFL may collaborate and complement other lenders to complete the debt package of a project (Co-Finance)BIFFL can be a part of Syndicated Loan &ldquo;as loans extended by multiple banks where the overall credit involved exceeds an individual lender&rsquo;s lending or other limits (Syndicated facility)</li>\r\n</ul>', 2, '2022-09-14 14:56:52', '2022-09-14 14:56:52', 'projects-finance', NULL),
(8, 'Advisory Services', '2017-12-16-5.jpg', 'hands-holding-small-tree-to-be-planted-free-photo.jpg', 'Structured Finance Unit provides following advisory services for project sponsors/entrepreneurs.\r\nReviewing preliminary/rudimentary business plan/concept note prepared by project sponsors.\r\nConducting market review/research report for the project.', '<p style=\"box-sizing: border-box; overflow-wrap: break-word; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; font-variant-numeric: normal; font-variant-east-asian: normal; font-stretch: normal; font-size: 16px; line-height: 26px; font-family: \'PT Sans\'; color: #444444; margin: 0px 0px 10px !important 0px;\"><strong style=\"box-sizing: border-box; margin: 0px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background: transparent;\">Structured Finance Unit provides following advisory services for project sponsors/entrepreneurs:</strong></p>\r\n<ul style=\"box-sizing: border-box; overflow-wrap: break-word; margin: 0px 0px 26px 30px; padding: 0px; border: 0px; outline: 0px; vertical-align: baseline; background-image: initial; background-position: initial; background-size: initial; background-repeat: initial; background-attachment: initial; background-origin: initial; background-clip: initial; list-style-position: initial; list-style-image: initial; color: #444444; font-family: \'PT Sans\'; font-size: 16px;\">\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Reviewing preliminary/rudimentary business plan/concept note prepared by project sponsors;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Conducting market review/research report for the project;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Drawing full-fledged, sound business/investment plans for the proposed project;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Devising an optimal financial structure/package for the proposed project;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Assisting project sponsor(s) in securing onshore and offshore finance;</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Joining project sponsor(s) in loan negotiation and documentation.</li>\r\n<li style=\"box-sizing: border-box; margin: 0px 0px 4px; padding: 0px 0px 0px 6px; border: 0px; outline: 0px; vertical-align: top; background: transparent;\">Structuring / designing financial model(s) for project(s).</li>\r\n</ul>', 2, '2022-09-14 14:58:13', '2022-09-14 14:58:13', 'advisory-services', NULL),
(10, 'Investment Criteria and Parameters', 'BIFFL LOGO_TR.png', 'padma4.png', 'It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.', '<p><span style=\"color: #101c54; font-family: \'Source Sans Pro\', sans-serif; font-size: 16px; letter-spacing: 0.4px;\">It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.</span></p>', 2, '2022-10-18 13:20:09', '2022-10-18 13:20:09', 'parameters', NULL),
