INSERT INTO `vsml_project` (`id`, `title`, `overview`, `video_1_title`, `video_1_link`, `video_2_title`, `video_2_link`, `product_1_title`, `product_1_document`, `product_2_title`, `product_2_document`, `product_3_title`, `product_3_document`, `product_4_title`, `product_4_link`, `add_info1`, `category`, `serial`, `status`, `created_at`, `updated_at`) VALUES
(31, 'First Dhaka Elevated Expressway (FDEE)', '<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">First Dhaka Elevated Expressway (FDEE) is Bangladesh&rsquo;s first elevated expressway project, which will connect the Shahjalal airport with Kutubkhali via Mohakhali, Tejgaon and Kamalapur of Dhaka. It is one of the largest infrastructure projects taken up by the incumbent government to ease traffic congestion in the capital.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">The CA was signed between the Government of People&rsquo;s Republic of Bangladesh, represented by Bridges Division, Ministry of Road Transport and Bridgess, acted through Bangladesh Bridge Authority (together the &ldquo;Grantor&rdquo;) , Bangladesh Bridge Authority (&ldquo;Grantor&rsquo;s Representative&rdquo;) and First Dhaka Elevated Expressway (FDEE) Company Limited (the &ldquo;Concessionaire&rdquo;) on January 2011.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">ITD established First Dhaka Elevated Expressway Company Limited (&ldquo;FDEE&rdquo; or the Concessionaire or the Company) as a 100%-owned Special Purpose Vehicle, registered in Bangladesh, to accede ITD as the Concessionaire in the Concession Agreement for implementation of the Project.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">ITD is the largest construction company in Thailand, listed on the Stock Exchange of Thailand (SET), with market share of about 29% of the total domestic construction business. The major shareholders of the company presently are the Karnasuta family members, holding about 33% shares of the company.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">The DEE Project involves the construction of a four-lane main carriageway and one elevated link road, comprising:</span></p>\r\n<ol style=\"list-style-type: lower-roman;\">\r\n<li><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">Four-lane dual Main Carriageway with a total length of 19.73 kilometers.</span></li>\r\n<li><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">Four-lane dual Link-Road Carriageway with a total length of 3.1 kilometers.</span></li>\r\n<li><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">32 on-off ramps (one-lane Carriageway of 5.5 meter width) of a total length of 23.9 kilometers. </span></li>\r\n<li><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12px; white-space: pre-wrap;\"><span style=\"font-size: 12pt;\">8 Toll Plazas and 43 Toll Collection Booths</span>.</span></li>\r\n</ol>\r\n<p><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12px; white-space: pre-wrap;\"><img src=\"../../uploads/images/gallery/FDEE.jpg\" alt=\"\" width=\"1280\" height=\"853\" /></span></p>', 'VISUAL PRESENTATION OF THE PROJECT', 'https://www.youtube.com/embed/wxrLT433iME?start=6', NULL, NULL, 'EIA OF THE PROJECT', 'EIA-FDEE-min.pdf', 'ROAD TRAFFIC MANAGEMENT PLAN OF THE PROJECT', 'Road-Traffic-Management-Plan_FDEE-min.pdf', 'RAILWAY TRAFFIC MANAGEMENT PLAN OF THE PROJECT', 'Railway-Traffic-Management-Plan_FDEE-min.pdf', NULL, NULL, NULL, 4, NULL, 1, '2022-09-25 18:55:41', NULL),
(32, 'Dhaka Bypass Expressway Development Company (DBED)', '<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">In 2020, the GOB signed an agreement with ADB for providing a 25-year-long credit line worth USD50 million to BIFFL for re-lending to the eligible subprojects structured in the PPP modality. The project aims to strengthen BIFFL&rsquo;s institutional capacity to develop and facilitate infrastructure projects. BIFFL is also receiving technical assistance of USD0.65 million as per the agreement. Meanwhile, BIFFL has signed the Common Terms Agreement and onshore facility agreement for providing a loan of BDT1,075 crore to the subproject implementing SPV &ldquo;Dhaka Bypass Expressway Development Company Ltd.&rdquo;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">The Dhaka By-pass Road is a strategic corridor for freight movement linking the manufacturing centre to the north of Dhaka with the centre of shipping activity at the port of Chittagong in the south. A two-stage bidding was conducted by RHD in 2017 for implementing the &ldquo;Upgrading of Joydevpur-Debogram-Bhulta-Madanpur (Dhaka By-pass) Road (N-105) into 4 Lanes through PPP, where the Consortium was identified as the Preferred Bidder through a rigorous technical and financial evaluation.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">Consortium of Sichuan Road and Bridge (Group) Corporation Limited (SRBG), Shamim Enterprise (Pvt.) Limited (SEL) and UDC Construction Limited (UDC) is in the process of forming a Project Company named Dhaka Bypass Expressway Development Company (DBEDC).</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">The PPP Contract of the Project has been signed on December 6, 2018 between the Roads and Highways Department (RHD) under the Ministry of Road Transport and Bridges and the Consortium.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #202124; font-family: consolas, \'lucida console\', \'courier new\', monospace; font-size: 12pt; white-space: pre-wrap;\">It is basically a 48 km 2 lane road which will be expanded to 4-lane by-pass connecting Joydevpur to Modonpur. The proposed subprojects include 6 new bridges for the mainline and service lanes, 8 new mainline overpasses, 46 existing box culverts and lengthened box culverts, 49 new culverts, 12 new channels and 8 pedestrian overpasses. It will connect the ongoing SASEC Road Connectivity project. Total project cost of the project is USD 358.83 million.</span></p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><img style=\"font-size: 16px;\" src=\"../../uploads/images/gallery/DBEDC.jpg\" alt=\"\" width=\"1427\" height=\"602\" /></p>', 'VISUAL PRESENTATION OF THE PROJECT', 'https://www.youtube.com/embed/nGNl19CrekQ', NULL, NULL, 'ESMS OF THE PROJECT', 'Final-Draft-BIFFL-ESMS.pdf', 'IEE OF THE PROJECT', 'IEE_EMP_Dhaka_Bypass_Road_Project_Final_10-03-2019.pdf', NULL, NULL, NULL, NULL, NULL, 5, NULL, 1, '2022-09-26 11:42:49', NULL);
