INSERT INTO `website_setting` (`id`, `phone`, `email`, `address`, `about`, `header_logo`, `footer_logo`, `facebook`, `twitter`, `instagram`, `linkedin`, `whatsup`, `pinterest`, `youtube`, `description`, `map`, `add_info1`, `add_info2`, `updated_at`) VALUES
(1, '+880-963-8124335', 'info@biffl.org.bd', 'Unique Heights, Level-3, 117 Kazi Nazrul Islam Avenue, Eskaton Garden, Dhaka-1217, Bangladesh.', 'Bangladesh Infrastructure Finance Fund Limited (BIFFL) is a Government-owned Non-Banking Financial Institution, operating since 2011. It is established by a resolution of the Cabinet of the Government of Bangladesh and owned by the Ministry of Finance, GOB', 'BIFFL LOGO for Website _final.png', 'logo.png', 'facebook.com', 'facebook.com', 'facebook.com', 'facebook.com', 'facebook.com', '+8802222228518', 'facebook.com', 'Bangladesh Infrastructure Finance Fund Limited (BIFFL) is the biggest Non-Banking Financial Institution in Bangladesh owned by Government having authorized capital and paid up capital of BDT 100 billion and BDT 20.10 billion respectively. Addressing the importance of infrastructure development vis-à-vis insufficient investment in that particular sector, with a view to promote an attractive environment for sustainable private investment.', 'https://www.biffl.org.bd', 'bifflfavicon.png', '0', '16236');
INSERT INTO `website_text` (`id`, `title`, `slug`, `short_description`, `description`, `add_info1`, `add_info2`, `serial_number`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Our Achievement Title', 'our-achievement', NULL, 'our achievements', NULL, NULL, NULL, 1, '2023-04-25 07:16:23', '2023-04-25 07:16:23'),
(2, 'About CEO', 'about-ceo', 'Mr. S. M. Anisuzzaman', 'Mr. S. M. Anisuzzaman, Chief Executive Officer, joined BIFFL on 4 May 2020. Before joining BIFFL, Mr. Anisuzzaman worked in National Housing Finance and Investments Limited as the Deputy Managing Director. He has attended 28 (twenty eight) meetings of the Board until May 2023. \r\n\r\nMr. Anisuzzaman, a skilled and adaptable management executive, has accumulated over 28 years of vast experience in the financial sector of Bangladesh. Throughout his lengthy career, he has occupied various senior roles in multiple banks and non-bank financial institutions (NBFIs). Due to his outstanding performance in the banking profession, he has received numerous accolades and has been honored with the ‘Best Manager’ award several times. \r\n\r\nAfter earning his B.Sc. in Civil Engineering from BUET, Mr. Anisuzzaman pursued an MBA in Strategic and International Management from the University of Dhaka. Moreover, he has participated in numerous training programs offered by prestigious national and international institutions. His profession has also led him to travel extensively across the globe, visiting many different countries.', 'about CEO - 3.jpg', 'Chief Executive Officer, BIFFL, and Ex-officio Member of the Board of Directors', NULL, 2, '2023-04-25 07:19:00', '2023-04-25 07:19:00'),
(3, 'About Chairman', 'about-chairman', 'Dr. Md. Khairuzzaman Mozumder', 'Dr. Md. Khairuzzaman Mozumder, Secretary, Finance Division joined as a Chairman to the Board of Directors of BIFFL on 30 September 2023 in the 118th Board Meeting of BIFFL. \r\nDr. Md. Khairuzzaman Mozumder is an accomplished professional with a 30-year career in various fields combining finance, macroeconomics, international economics, customs, trade facilitation issues, international development, WTO issues, and international trade. Before joining the Finance Division, Ministry of Finance, he served as Secretary of the Energy and Mineral Resources Division under the Ministry of Power, Energy and Mineral Resources. He joined the Bangladesh Civil Service in April 1993 and later served in various positions of BCS (Customs & Excise) in the National Board of Revenue under the Ministry of Finance.', 'Dr. Khairuzzaman - 4.jpg', 'Chairman, BIFFL, and Secretary, Finance Division, Ministry of Finance', NULL, 2, '2023-04-25 07:19:27', '2023-04-25 07:19:27'),
(4, 'Area of Investment', 'our-services-title', NULL, 'Areas of Investment', 'ITD.jpg', NULL, NULL, 1, '2023-05-07 06:34:24', '2023-05-07 06:34:24'),
